using UnityEngine; namespace Mojinloop.Gameplay { [RequireComponent(typeof(Animator))] public sealed class HeroAnimationController:MonoBehaviour { static readonly int IsRunningHash=Animator.StringToHash("IsRunning"),IsAttackingHash=Animator.StringToHash("IsAttacking"); [SerializeField] Animator animator; void Reset(){animator=GetComponent<Animator>();} void Awake(){if(animator==null)animator=GetComponent<Animator>();} public void Apply(HeroState state){if(animator==null)return;animator.SetBool(IsRunningHash,state==HeroState.Running);animator.SetBool(IsAttackingHash,state==HeroState.Attacking);} } }
